"""Highest version in a list satisfying an npm-style range. See task.md."""

from __future__ import annotations

import operator
import re


class RangeError(ValueError):
    """Raised for malformed range expressions and malformed versions."""


_NUM = r"0|[1-9][0-9]*"
_IDENT = r"[0-9A-Za-z-]+"
_DOTTED = rf"{_IDENT}(?:\.{_IDENT})*"
_FULL_RE = re.compile(rf"({_NUM})\.({_NUM})\.({_NUM})(?:-({_DOTTED}))?(?:\+{_DOTTED})?")
_PART = rf"(?:{_NUM}|[xX*])"
_PARTIAL_RE = re.compile(rf"({_PART})(?:\.({_PART}))?(?:\.({_PART}))?")
_WILDCARDS = ("x", "X", "*")
_OPERATORS = (">=", "<=", ">", "<", "=", "^", "~")
_COMPARE = {
    "=": operator.eq,
    ">": operator.gt,
    ">=": operator.ge,
    "<": operator.lt,
    "<=": operator.le,
}


def _pre_keys(pre: str) -> tuple:
    keys = []
    for ident in pre.split("."):
        if ident.isdigit():
            if len(ident) > 1 and ident[0] == "0":
                raise RangeError(f"leading zero in prerelease identifier: {pre!r}")
            keys.append((0, int(ident)))
        else:
            keys.append((1, ident))
    return tuple(keys)


def _precedence(core: tuple, pre: tuple | None) -> tuple:
    return core + ((1,) if pre is None else (0, pre))


def _parse_version(text: str) -> tuple[tuple, tuple | None]:
    m = _FULL_RE.fullmatch(text)
    if m is None:
        raise RangeError(f"malformed version: {text!r}")
    core = tuple(int(g) for g in m.group(1, 2, 3))
    pre = _pre_keys(m.group(4)) if m.group(4) is not None else None
    return core, pre


def _parse_comparand(text: str) -> tuple[list[int], tuple | None]:
    m = _FULL_RE.fullmatch(text)
    if m is not None:
        pre = _pre_keys(m.group(4)) if m.group(4) is not None else None
        return [int(g) for g in m.group(1, 2, 3)], pre
    m = _PARTIAL_RE.fullmatch(text)
    if m is None:
        raise RangeError(f"malformed version: {text!r}")
    nums: list[int] = []
    wild = False
    for part in m.groups():
        if part is None:
            continue
        if part in _WILDCARDS:
            wild = True
        elif wild:
            raise RangeError(f"malformed version: {text!r}")
        else:
            nums.append(int(part))
    return nums, None


def _complete(nums: list[int]) -> tuple:
    return tuple(nums) + (0,) * (3 - len(nums))


def _bump(nums: list[int], index: int) -> tuple:
    return tuple(nums[:index]) + (nums[index] + 1,) + (0,) * (2 - index)


def _partial_bounds(nums: list[int]) -> list[tuple]:
    if not nums:
        return [(">=", (0, 0, 0), None)]
    return [(">=", _complete(nums), None), ("<", _bump(nums, len(nums) - 1), None)]


def _desugar(token: str) -> list[tuple]:
    op = next((o for o in _OPERATORS if token.startswith(o)), "")
    nums, pre = _parse_comparand(token[len(op):])

    if op in (">", ">=", "<", "<="):
        if len(nums) != 3:
            raise RangeError(f"operator {op} requires a full version: {token!r}")
        return [(op, tuple(nums), pre)]

    if op in ("", "="):
        if len(nums) == 3:
            return [("=", tuple(nums), pre)]
        return _partial_bounds(nums)

    if not nums:
        raise RangeError(f"missing major version: {token!r}")
    if op == "^":
        index = next((k for k, n in enumerate(nums) if n), len(nums) - 1)
    else:
        index = 1 if len(nums) >= 2 else 0
    return [(">=", _complete(nums), pre), ("<", _bump(nums, index), None)]


def _hyphen(low: str, high: str) -> list[tuple]:
    low_nums, low_pre = _parse_comparand(low)
    high_nums, high_pre = _parse_comparand(high)
    if not low_nums or not high_nums:
        raise RangeError(f"hyphen range bounds need a major version: {low!r} - {high!r}")
    prims = [(">=", _complete(low_nums), low_pre)]
    if len(high_nums) == 3:
        prims.append(("<=", tuple(high_nums), high_pre))
    else:
        prims.append(("<", _bump(high_nums, len(high_nums) - 1), None))
    return prims


def _parse_comparator_set(tokens: list[str]) -> list[tuple]:
    if "-" in tokens:
        if len(tokens) != 3 or tokens[1] != "-":
            raise RangeError(f"malformed hyphen range: {' '.join(tokens)!r}")
        return _hyphen(tokens[0], tokens[2])
    prims: list[tuple] = []
    for token in tokens:
        prims.extend(_desugar(token))
    return prims


def _parse_range(range_expr: str) -> list[list[tuple]]:
    if not range_expr.strip():
        return [[(">=", (0, 0, 0), None)]]
    sets = []
    for side in range_expr.split("||"):
        tokens = side.split()
        if not tokens:
            raise RangeError(f"empty comparator set in {range_expr!r}")
        sets.append(_parse_comparator_set(tokens))
    return sets


def _satisfies_set(core: tuple, pre: tuple | None, prims: list[tuple]) -> bool:
    key = _precedence(core, pre)
    for op, pcore, ppre in prims:
        if not _COMPARE[op](key, _precedence(pcore, ppre)):
            return False
    if pre is None:
        return True
    return any(ppre is not None and pcore == core for _, pcore, ppre in prims)


def max_satisfying(versions: list[str], range_expr: str) -> str | None:
    """Return the highest version in `versions` that satisfies `range_expr`."""
    sets = _parse_range(range_expr)
    best = None
    best_key = None
    for text in versions:
        core, pre = _parse_version(text)
        key = _precedence(core, pre)
        if best_key is not None and key <= best_key:
            continue
        if any(_satisfies_set(core, pre, prims) for prims in sets):
            best, best_key = text, key
    return best
